import{_ as p,a0 as l,w as d,s,ao as i,I as a,x as t,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何交互式地創建一個Docker容器 | LCTT x X-CMD","titleTemplate":false,"description":"如何交互式地創建一個Docker容器 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何交互式地創建一個Docker容器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何交互式地創建一個Docker容器 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150324 How to Interactively Create a Docker Container","title":"如何交互式地創建一個Docker容器","tag":"201505","desc":""},"relativePath":"201505/20150324 How to Interactively Create a Docker Container.md","filePath":"[post].md"}'),c={name:"201505/20150324 How to Interactively Create a Docker Container.md"};function m(g,e,h,u,k,f){const o=l("Link");return d(),s("div",null,[e[16]||(e[16]=i('<h1 id="如何交互式地創建一個docker容器" tabindex="-1">如何交互式地創建一個Docker容器 <a class="header-anchor" href="#如何交互式地創建一個docker容器" aria-label="Permalink to “如何交互式地創建一個Docker容器”">​</a></h1><p>大家好，今天我們來學習如何使用一個docker鏡像交互式地創建一個Docker容器。當我們從鏡像中啓動一個Docker進程，Docker就會獲取該鏡像及其父鏡像，並重復這個過程，直到到達基礎鏡像。然後聯合文件系統（UFS）會在其頂層添加一個讀寫層。讀寫層被稱之為容器，它包含了一些關於父鏡像信息及一些其他的信息，如唯一ID，網絡配置和資源限制等。容器是有狀態的，其狀態可以從 <strong>運行態</strong> 切換到 <strong>退出態</strong>。一個處於 <strong>運行態</strong>的容器包含了在CPU上面運行的進程樹，於其它在該主機上運行的進程相隔離，而<strong>退出態</strong>是指文件系統的狀態，並保留了其退出值。你可以使用它來啓動，停止和重啓一個容器。</p><p>Docker技術為IT界帶來了巨大的改變，它使得雲服務可以用來共享應用和工作流程自動化，使得應用可以用組件快速組合，消除了開發、品質保證、產品環境間的摩擦。在這篇文章中，我們將會建立CentOS環境，然後用Apache網絡服務器提供一個網站服務。</p><p>這是一個快速且容易的教程，討論我們怎樣使用交互的shell，以交互的方式來創建一個容器。</p><h3 id="_1-運行一個docker實例" tabindex="-1">1. 運行一個Docker實例 <a class="header-anchor" href="#_1-運行一個docker實例" aria-label="Permalink to “1. 運行一個Docker實例”">​</a></h3>',5)),a("p",null,[e[1]||(e[1]=t("Docker首先會嘗試從本地取得並運行所需的鏡像，如果在本地主機上沒有發現，它就會從",-1)),r(o,{href:"https://registry.hub.docker.com/"},{default:n(()=>[...e[0]||(e[0]=[t("Docker公共註冊中心",-1)])]),_:1}),e[2]||(e[2]=t("拉取。這裏，我們將會拉取鏡像並在 Docker 容器中創建一個fedora實例，並連接到它的 tty 上的bash shell。",-1))]),e[17]||(e[17]=i(`<pre><code># docker run -i -t fedora bash
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/downloading-fedora-base-image.png" alt="Downloading Fedora Base Image"></p><h3 id="_2-安裝apache網絡服務器" tabindex="-1">2.安裝Apache網絡服務器 <a class="header-anchor" href="#_2-安裝apache網絡服務器" aria-label="Permalink to “2.安裝Apache網絡服務器”">​</a></h3><p>現在，在我們的Fedora基本鏡像實例準備好後，我們將會開始交互式地安裝Apache網絡服務器，而不是為它創建Dockerfile。為了做到這點，我們需要在終端或者shell運行以下命令。</p><pre><code># yum update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-httpd2.png" alt="Installing httpd"></p><pre><code># yum install httpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-httpd2.png" alt="Installing httpd"></p><pre><code># exit
</code></pre><h3 id="_3-保存鏡像" tabindex="-1">3.保存鏡像 <a class="header-anchor" href="#_3-保存鏡像" aria-label="Permalink to “3.保存鏡像”">​</a></h3><p>現在，我們要去保存在Fedora實例裏做的修改。要做到這個，我們首先需要知道實例的容器ID。而為了得到ID，我們又需要運行以下命令（LCTT 譯註：在容器外執行該命令）。</p><pre><code># docker ps -a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/docker-running-container.png" alt="Docker Running Container"></p><p>然後，我們會保存這些改變為一個新的鏡像，請運行以下命令。</p><pre><code># docker commit c16378f943fe fedora-httpd
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/committing-fedora-httpd.png" alt="committing fedora httpd"></p><p>這裏，修改已經通過使用容器ID保存起來了，鏡像名字叫fedora-httpd。為了確認新的鏡像是否在運行，我們將運行以下命令。</p><pre><code># docker images
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/view-docker-images.png" alt="view docker images"></p><h3 id="_4-添加內容到新的鏡像" tabindex="-1">4. 添加內容到新的鏡像 <a class="header-anchor" href="#_4-添加內容到新的鏡像" aria-label="Permalink to “4. 添加內容到新的鏡像”">​</a></h3><p>我們自己新的Fedora Apache鏡像正成功的運行，現在我們想添加一些我們網站的網頁內容到Apache網絡服務器，使得網站能夠開箱即用。為做到這點，我們需要創建一個新的Dockerfile，它會處理從複製網頁內容到啓用80端口的所有操作。要達到這樣的目的，我們需要使用我們最喜歡的文本編輯器創建Dockerfile文件，像下面演示的一樣。</p><pre><code># nano Dockerfile
</code></pre><p>現在，我們需要添加以下的命令列到文件中。</p><pre><code>FROM fedora-httpd
ADD mysite.tar /tmp/
RUN mv /tmp/mysite/* /var/www/html
EXPOSE 80
ENTRYPOINT [ &quot;/usr/sbin/httpd&quot; ]
CMD [ &quot;-D&quot;, &quot;FOREGROUND&quot; ]
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/configuring-Dockerfile.png" alt="configuring Dockerfile"></p><p>這裏，上述的Dockerfile中，放在mysite.tar裏的網頁內容會自動解壓到/tmp/文件夾裏。然後，整個站點會被移動到Apache的網頁根目錄/var/www/html/，命令expose 80會打開80端口，這樣網站就能正常訪問了。其次，入口點放在了/usr/sbin/https裏面，保證Apache服務器能夠執行。</p><h3 id="_5-構建並運行一個容器" tabindex="-1">5. 構建並運行一個容器　### <a class="header-anchor" href="#_5-構建並運行一個容器" aria-label="Permalink to “5. 構建並運行一個容器　###”">​</a></h3><p>現在，我們要用剛剛創建的Dockerfile創建我們的容器，以便將我們的網站添加到上面。為做到這，我們需要運行以下命令。</p><pre><code># docker build -rm -t mysite .
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/building-mysite-image.png" alt="Building mysite Image"></p><p>建立好我們的新容器後，我們需要要用下面的命令來運行容器。</p><pre><code># docker run -d -P mysite
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/running-mysite-container.png" alt="Running mysite Container"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>最後，我們已經成功的以交互式的方式建立了一個Docker容器。在本節方法中，我們是直接通過交互的shell命令建立我們的容器和鏡像。在建立與配置鏡像與容器時，這種方法十分簡單且快速。如果你有任何問題，建議和反饋，請在下方的評論框裏寫下來，以便我們可以提升或者更新我們的文章。謝謝！祝生活快樂 😃</p><hr>`,36)),a("p",null,[e[4]||(e[4]=t("via: ",-1)),r(o,{href:"http://linoxide.com/linux-how-to/interactively-create-docker-container/"},{default:n(()=>[...e[3]||(e[3]=[t("http://linoxide.com/linux-how-to/interactively-create-docker-container/",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=t("作者：",-1)),r(o,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[5]||(e[5]=[t("Arun Pyasi",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),r(o,{href:"https://github.com/wi-cuckoo"},{default:n(()=>[...e[6]||(e[6]=[t("wi-cuckoo",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[13]||(e[13]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const T=p(c,[["render",m]]);export{b as __pageData,T as default};
